// C# 14: field keyword — no explicit backing field needed
public class Config {
  public string ConnectionString {
    get;
    set => field = value ?? throw new ArgumentNullException(nameof(value));
    //     ^^^^^ implicit backing field — no _connectionString needed!
  }
}

// C# 13 equivalent (verbose)
public class Config13 {
  private string _cs;
  public string ConnectionString {
    get => _cs;
    set => _cs = value ?? throw new ArgumentNullException(nameof(value));
  }
}

